const { chromium } = await import('/Users/marcel.a.n.navarro/Dev/zimmermann-pwa/node_modules/playwright/index.mjs');
const b = await chromium.launch();
const p = await b.newPage({ viewport: { width: 900, height: 700 } });
await p.goto('http://127.0.0.1:52860/iframe.html?id=commerce-zimmproductdescription--default&viewMode=story',
  { waitUntil: 'networkidle' });
await p.waitForSelector('[data-testid="product-description"] ul');

const out = await p.evaluate(() => {
  const root = document.querySelector('[data-testid="product-description"]');
  const ul = root.querySelector('ul');
  const li = ul.querySelector('li');
  const wrapper = root.parentElement;              // the 218px Box decorator
  const cs = getComputedStyle(ul);
  const csRoot = getComputedStyle(root);

  const textStartX = (el) => {
    const tn = [...el.childNodes].find(n => n.nodeType === 3 && n.textContent.trim());
    const r = document.createRange(); r.selectNodeContents(tn);
    // trim leading whitespace effect by using the first client rect
    return r.getClientRects()[0].left;
  };

  const liRect = li.getBoundingClientRect();
  const liCS = getComputedStyle(li);
  const liContentLeft = liRect.left + parseFloat(liCS.paddingLeft) + parseFloat(liCS.borderLeftWidth);

  const outsideTextX = textStartX(li);

  // measure the marker's real advance width: with list-style-position:inside the marker
  // becomes part of the first line box, so the text shifts right by exactly its advance.
  ul.style.listStylePosition = 'inside';
  const insideTextX = textStartX(li);
  ul.style.listStylePosition = '';

  const markerAdvance = insideTextX - outsideTextX;

  return {
    computed: {
      listStyleType: cs.listStyleType,
      listStylePosition: cs.listStylePosition,
      paddingInlineStart: cs.paddingInlineStart,
      marginBlockStart: cs.marginBlockStart,
    },
    rootFontSize: getComputedStyle(document.documentElement).fontSize,
    descriptionFontSize: csRoot.fontSize,
    wrapperWidth: wrapper.getBoundingClientRect().width,
    wrapperLeft: wrapper.getBoundingClientRect().left,
    ulLeft: ul.getBoundingClientRect().left,
    ulWidth: ul.getBoundingClientRect().width,
    liContentLeft,
    markerAdvance: Math.round(markerAdvance * 100) / 100,
    markerLeftEdge: Math.round((liContentLeft - markerAdvance) * 100) / 100,
    // clipping / overflow checks
    wrapperOverflowX: wrapper.scrollWidth - wrapper.clientWidth,
    ulOverflowX: ul.scrollWidth - ul.clientWidth,
    rootOverflowX: root.scrollWidth - root.clientWidth,
    rootOverflowStyle: csRoot.overflowX,
    liCount: ul.querySelectorAll('li').length,
  };
});
console.log(JSON.stringify(out, null, 2));
console.log('--- VERDICT ---');
const insetOfMarker = out.markerLeftEdge - out.wrapperLeft;
console.log('marker left edge, relative to the 218px column left edge:', Math.round(insetOfMarker*100)/100, 'px');
console.log('marker advance width:', out.markerAdvance, 'px   indent:', out.computed.paddingInlineStart);
console.log('fits inside column:', insetOfMarker >= 0 && out.markerAdvance <= parseFloat(out.computed.paddingInlineStart));
await p.locator('[data-testid="product-description"]').screenshot({ path: '/tmp/desc_markers.png' });
await b.close();
