const { chromium } = await import('/Users/marcel.a.n.navarro/Dev/zimmermann-pwa/node_modules/playwright/index.mjs');
const b = await chromium.launch();
const p = await b.newPage({ viewport: { width: 900, height: 700 }, deviceScaleFactor: 4 });
await p.goto('http://127.0.0.1:52860/iframe.html?id=commerce-zimmproductdescription--default&viewMode=story',
  { waitUntil: 'networkidle' });
await p.waitForSelector('[data-testid="product-description"] ul');
// force an opaque white backdrop so luminance thresholding is unambiguous
await p.evaluate(() => { document.body.style.background = '#fff'; });

const PAD = 24; // px of page captured to the LEFT of the column edge

async function inkScan(label) {
  const geo = await p.evaluate((PAD) => {
    const root = document.querySelector('[data-testid="product-description"]');
    const ul = root.querySelector('ul');
    const li = ul.querySelector('li');
    const w = root.parentElement.getBoundingClientRect();
    const lr = li.getBoundingClientRect();
    return { clip: { x: w.left - PAD, y: lr.top, width: PAD + 40, height: Math.min(lr.height, 20) },
             columnLeft: w.left, ulPad: getComputedStyle(ul).paddingInlineStart };
  }, PAD);

  const buf = await p.screenshot({ clip: geo.clip });
  const dataUrl = 'data:image/png;base64,' + buf.toString('base64');
  const scan = await p.evaluate(async (dataUrl) => {
    const img = new Image();
    await new Promise((r) => { img.onload = r; img.src = dataUrl; });
    const c = document.createElement('canvas');
    c.width = img.naturalWidth; c.height = img.naturalHeight;
    const ctx = c.getContext('2d');
    ctx.drawImage(img, 0, 0);
    const d = ctx.getImageData(0, 0, c.width, c.height).data;
    let minX = null, maxX = null;
    for (let x = 0; x < c.width; x++) {
      for (let y = 0; y < c.height; y++) {
        const i = (y * c.width + x) * 4;
        const lum = 0.299 * d[i] + 0.587 * d[i + 1] + 0.114 * d[i + 2];
        if (d[i + 3] > 40 && lum < 140) { if (minX === null) minX = x; maxX = x; break; }
      }
      if (minX !== null && x - maxX > 8 * 4) break; // stop after a clear gap (marker only)
    }
    return { minX, maxX, w: c.width, h: c.height };
  }, dataUrl);

  const dpr = scan.w / geo.clip.width;                    // device px per css px
  const inkLeftCss = scan.minX / dpr - PAD;               // relative to the column's left edge
  const inkRightCss = scan.maxX / dpr - PAD;
  console.log(`[${label}] indent=${geo.ulPad}  first ink (the disc): left=${inkLeftCss.toFixed(2)}px  right=${inkRightCss.toFixed(2)}px  (relative to the 218px column's left edge; negative = overhangs)`);
  console.log(`[${label}] visible disc width = ${(inkRightCss - inkLeftCss).toFixed(2)}px   OVERHANGS COLUMN: ${inkLeftCss < 0}`);
  return inkLeftCss;
}

const shipped = await inkScan('SHIPPED  paddingInlineStart:16px');
await p.evaluate(() => {
  document.querySelector('[data-testid="product-description"] ul').style.paddingInlineStart = '0px';
});
const zeroed = await inkScan('COUNTERFACTUAL padding:0 (pre-fix)');
console.log('\n--- delta ---');
console.log('the 16px indent moves the disc', (shipped - zeroed).toFixed(2), 'px to the right of where padding:0 puts it');
await b.close();
EOF
